def filter_by_channel(page, channel_keyword):
    """在「全部渠道」多选弹层里选中 == channel_keyword 的渠道并确定。channel_keyword=None 不筛选。
    实测：触发控件 input[placeholder*='渠道']；渠道选项是 span.main_label（精确匹配文本，
    别用包含匹配——订单行 物流信息列 也含渠道文字会误点）；弹层有 取消/确定。"""
    if not channel_keyword:
        return True
    try:
        dismiss_notifications(page)   # 先清右上角通知浮层，否则会拦截点击
        page.click("input[placeholder*='渠道']", timeout=5000, force=True)
        time.sleep(1.2)
        picked = False
        for el in page.query_selector_all("span.main_label"):
            try:
                if el.is_visible() and (el.inner_text() or "").strip() == channel_keyword:
                    el.click(); picked = True
                    log(f"[ERP] 渠道选中: {channel_keyword}")
                    break
            except Exception:
                continue
        if not picked:
            # 打出下拉里【实际可选】的渠道，便于判断是「该渠道确实无正常单(模板已排除取消单)」
            # 还是「有单却漏筛」。需求1 选模板会排除取消/退款/换货/禁处理单，这些渠道可能不再出现。
            try:
                avail = page.evaluate(r"""() => [...document.querySelectorAll('span.main_label')]
                    .filter(e=>e.offsetParent!==null).map(e=>(e.innerText||'').trim()).filter(Boolean)""")
            except Exception:
                avail = []
            log(f"[ERP] 未找到渠道选项: {channel_keyword}；当前下拉可选渠道={sorted(set(avail))}")
            try: page.keyboard.press("Escape")
            except Exception: pass
            return False
        time.sleep(0.5)
        # 确定（限可见弹层）
        for t in ["确定", "确认"]:
            b = page.query_selector(f".el-popper:visible button:has-text('{t}')")
            if not (b and b.is_visible()):
                b = page.query_selector(f"button:has-text('{t}'):visible")
            if b and b.is_visible():
                b.click(); break
        time.sleep(2.5)
        return True
    except Exception as e:
        log(f"[ERP] 渠道筛选失败: {e}")
        return False


