// content_erp.js —— ERP（赛狐 Sellfox）页面内操作，照搬 automation/erp.py。
// 由 background 注入到 sellfox.com 的所有 frame；只有承载订单表(vxe)的那个 frame 会真正干活，
// 其余 frame 的 dispatch 返回 null，被 background 过滤掉。
// 每个 op 把过程日志 push 进 L，随结果一起返回，由 background 转发到 popup 实时显示。
window.__HWC_ERP = window.__HWC_ERP || (function () {
  const H = window.__HWC;
  const FILTER_TEMPLATE = "未取消等待发货";

  // 该 frame 是否承载订单业务视图？（有 vxe 表格 或 待处理/物流下单 相关 DOM）
  function isErpFrame() {
    return !!(document.querySelector(".vxe-table, .vxe-header--column") ||
              H.findByExactText("物流下单") ||
              H.qsa("*").some((e) => e.children.length === 0 && H.norm(e.innerText) === "待处理"));
  }

  function dismissNotifications() {
    try { H.qsa(".el-notification").forEach((e) => e.remove()); } catch (e) {}
  }

  // 等模板 popover 与 loading 遮罩都消失再操作。实测坑(2026-07-15)：选中筛选模板后，模板 popover
  // 残留 + 列表刷新 loading 遮罩，会让紧接着的渠道 input 点击弹不开渠道下拉（单例 popover 被占/
  // 遮罩拦点）——现象=模板成功那次渠道三次全未弹开、模板失败那次渠道反而能开（强相关）。
  const BLOCKER_SEL = ".el-popover, .select-menu, .search_more_temp_new, .el-loading-mask, .loading-indicator-overlay, .vxe-loading--wrapper";
  async function waitPageSettle(timeout = 6000) {
    await H.waitFor(() => !H.qsa(BLOCKER_SEL).some((p) => H.isVisible(p)), { timeout, interval: 300 });
  }
  function visibleBlockers() {
    return [...new Set(H.qsa(BLOCKER_SEL).filter((e) => H.isVisible(e))
      .map((e) => (typeof e.className === "string" ? e.className : "").split(" ")[0]).filter(Boolean))];
  }

  // 元素简描：标签+前3个class+placeholder+短文本。用于报错时说清「到底定位到了什么」。
  function describeEl(el) {
    if (!el) return "null";
    const cls = (typeof el.className === "string" ? el.className : "").trim().split(/\s+/).filter(Boolean).slice(0, 3).join(".");
    const ph = el.placeholder ? ` ph="${el.placeholder}"` : "";
    const txt = H.norm(el.innerText || "").slice(0, 24);
    return `<${el.tagName.toLowerCase()}${cls ? "." + cls : ""}${ph}>${txt ? ` "${txt}"` : ""}`;
  }
  // 输入框祖先链的首个 class（最多 5 层）——判断真正该点哪一层容器才能弹开下拉。
  function ancestorClasses(el, depth = 5) {
    const a = []; let p = el && el.parentElement;
    for (let i = 0; i < depth && p; i++) {
      const c = (typeof p.className === "string" ? p.className : "").trim().split(/\s+/)[0];
      if (c) a.push(c);
      p = p.parentElement;
    }
    return a;
  }
  // 渠道相关 DOM 现状快照。ERP 改版(placeholder/class 改了)时，一眼看出「渠道输入框」为何没命中。
  function channelDomSnapshot() {
    const inputs = [...new Set(H.qsa("input").filter(H.isVisible)
      .map((e) => e.placeholder || "(无placeholder)"))].slice(0, 25);
    const chanTexts = [...new Set(H.qsa("span, div, label, button")
      .filter((e) => H.isVisible(e) && e.children.length <= 2 && /渠道/.test(e.innerText || ""))
      .map((e) => H.norm(e.innerText)).filter(Boolean))].slice(0, 10);
    return { 可见input的placeholder: inputs, 含渠道字样的可见元素: chanTexts };
  }

  async function dismissAlertModal(L) {
    for (let i = 0; i < 3; i++) {
      let closed = false;
      for (const t of ["稍后处理", "关闭", "我知道了", "取消"]) {
        const b = H.qsa(".el-dialog button, .el-message-box button")
          .find((x) => H.isVisible(x) && H.norm(x.innerText) === H.norm(t));
        if (b) { H.realClick(b); closed = true; await H.sleep(800); break; }
      }
      if (!closed) break;
    }
  }

  async function gotoView(name, L) {
    const el = H.findByExactText(name);
    if (!el) { L.push(`[ERP] 未找到视图入口：${name}`); return false; }
    H.realClick(el);
    await H.sleep(3000);
    L.push(`[ERP] 切换到视图：${name}`);
    return true;
  }

  // 需求1：选筛选模板（排除取消/退款/换货/禁处理单）。⚠️实测选模板会重置渠道筛选，
  // 故调用方必须【先选模板，再筛渠道】，让渠道筛选最后生效（安全底线）。
  async function selectFilterTemplate(name, L) {
    if (!name) return true;
    dismissNotifications();
    // 触发器直接用 class 定位（探测实证 reference class=search_more_temp_reference）——比 findByExactText
    // 文本匹配可靠：页面别处也有「筛选模板」文字（如"更多筛选"区），findByExactText 取 y 最靠上易选错、
    // 点了不弹 popover（实测 run 里三次重试都没弹开=定位错了触发器）。兜底再退回叶子文本匹配。
    const trigger = document.querySelector(".search_more_temp_reference")
      || H.qsa("span, div, a, button").find((e) => H.isVisible(e) && e.children.length === 0 && H.norm(e.innerText) === "筛选模板")
      || H.findByExactText("筛选模板");
    if (!trigger) { L.push("[ERP] 未找到『筛选模板』触发控件"); return false; }
    // 模板选项异步渲染 + 合成点击偶发不生效（实测探测两次一次弹开一次没弹）。轮询等选项出现、
    // 最多重试 3 轮点击，别固定 sleep 后就读。只匹配叶子(children.length===0)——探测确认
    // 「未取消等待发货」是 cls="" 独立叶子 span，不限叶子会误命中包含它的容器。
    const findOpt = () => H.qsa("span, div, li, a")
      .find((e) => H.isVisible(e) && e.children.length === 0 && H.norm(e.innerText) === H.norm(name));
    let opt = null;
    for (let attempt = 0; attempt < 3 && !opt; attempt++) {
      H.realClick(trigger);
      opt = await H.waitFor(() => findOpt(), { timeout: 4000, interval: 300 });
      if (!opt) { L.push(`[ERP] 筛选模板选项未出现(第${attempt + 1}次)，重试…`); await H.sleep(600); }
    }
    if (!opt) {
      L.push(`[ERP] 未找到筛选模板选项：${name}`);
      // 关键：找不到也要按 Esc 关掉筛选模板弹层，否则它是 single_el_popover 单例弹层，
      // 残留开着会导致下一步点渠道 input 只关旧弹层、不弹渠道下拉（实测渠道选项为空）。
      try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
      await H.sleep(400);
      return false;
    }
    H.realClick(opt);
    await H.sleep(1500);
    // 主动关闭模板 popover（Element el-popover 选项点选后不一定自动关；残留会占用单例弹层机制、
    // 导致下一步渠道 input 点击只被消费为"关模板"而不弹渠道下拉=实测渠道三次未弹开）。
    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
    try { document.body.click(); } catch (e) {}
    await waitPageSettle();
    L.push(`[ERP] 已选择筛选模板：${name}`);
    return true;
  }

  // 渠道筛选。触发 input[placeholder*='渠道'] -> 弹层 span.main_label 精确匹配 -> 确定。
  // 返回 {ok, available}。available = 找不到时下拉里实际可选渠道（便于判断是漏筛还是本就没单）。
  async function filterByChannel(channel, L) {
    if (!channel) return { ok: true };
    dismissNotifications();
    // 先按 Esc 清掉可能残留的弹层（如上一步筛选模板未关的 popover）。渠道弹层是 single_el_popover
    // 单例机制：若有旧弹层开着，点渠道 input 只会关旧弹层、不弹渠道下拉 → 选项为空（实测）。
    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
    await H.sleep(400);
    // 点渠道 input 前先等页面稳定（模板 popover/loading 遮罩残留会让下拉弹不开）。
    await waitPageSettle();
    if (!document.querySelector("input[placeholder*='渠道']")) {
      // ⚠️定位失败（选择器 input[placeholder*='渠道'] 没命中）。ERP 改版最可能卡在这里：
      // placeholder 文案改了 / 渠道筛选变成非 input 控件。dump 现状让人一眼看出新写法。
      L.push(`[ERP] ❌ 未定位到渠道筛选输入框——选择器 input[placeholder*='渠道'] 无命中（疑 ERP 界面改版）。`
        + `当前页 DOM 快照=${JSON.stringify(channelDomSnapshot())}`);
      return { ok: false, available: [], reason: "渠道输入框选择器未命中(可能改版)" };
    }
    // 渠道选项异步加载(虚拟滚动 vue-recycle-scroller) + 合成点击偶发不生效；且实测「模板一应用→渠道
    // 三次全不弹开且 blockers=[]」→ 疑模板刷新使工具栏重渲染、旧 input 引用失效。故【每轮重新抓 input】
    // + focus+click(探测证实 focus+click 也能弹开)，未弹开时打细诊断(connected/disabled/下拉容器数)。
    // 【自适应点法】独立探测总在"模板应用后"这步超时(页面卡顿)，故把"试多种点法"直接内建到生产流程：
    // 依次尝试 5 种点法，哪种让 span.main_label 冒出来就用哪种、并记录点法名（下次日志即知哪种有效）。
    // 病根候选：模板应用后渠道 el-popover 触发被抑制；不同点法(双击/focus/点外层 popover_trigger)或能破。
    // 关键实测(2026-07-15)：模板应用后点渠道，弹层【确实开了】(el-popover+select-menu 可见)，但里面
    // span.main_label【空】=选项没加载出来。故区分「弹层开」与「选项到位」：弹层一开就耐心等选项(8s，
    // 不急着换点法/不 Escape 打断加载)；等够还空就 dump 弹层内部结构，定性是"加载中/暂无/虚拟滚动没渲染"。
    const readLabels = () => H.qsa("span.main_label").filter((e) => H.isVisible(e));
    const ddOpen = () => H.qsa(".el-popover, .select-menu").some((e) => H.isVisible(e));
    const chan = () => document.querySelector("input[placeholder*='渠道']");
    const openers = [
      { name: "realClick", fn: () => H.realClick(chan()) },
      { name: "双击", fn: async () => { H.realClick(chan()); await H.sleep(300); H.realClick(chan()); } },
      { name: "focus+click", fn: () => { const i = chan(); try { i.focus(); } catch (e) {} H.realClick(i); } },
      { name: "popover_trigger", fn: () => { const t = chan() && chan().closest(".popover_trigger"); if (t) H.realClick(t); } },
      { name: "select-container", fn: () => { const t = chan() && chan().closest(".select-container"); if (t) H.realClick(t); } },
    ];
    let labels = [];
    let usedOpener = "";
    for (const op of openers) {
      if (!chan()) break;
      try { await op.fn(); } catch (e) {}
      const opened = await H.waitFor(() => (ddOpen() || readLabels().length) ? true : null, { timeout: 2500, interval: 200 });
      if (!opened) {
        L.push(`[ERP] 渠道点法「${op.name}」弹层未开，换下一种…`);
        try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
        await H.sleep(400);
        continue;
      }
      // 弹层开了，耐心等选项加载（虚拟滚动/异步）
      const got = await H.waitFor(() => { const l = readLabels(); return l.length ? l : null; }, { timeout: 8000, interval: 400 });
      if (got && got.length) { labels = got; usedOpener = op.name; break; }
      // 弹层开着但选项一直空 → dump 内部结构诊断（换点法无意义，是数据/加载问题）
      const dd = H.qsa(".el-popover, .select-menu").find((e) => H.isVisible(e));
      const info = dd ? {
        文本: (dd.innerText || "").replace(/\s+/g, " ").trim().slice(0, 140),
        有搜索框: !!dd.querySelector("input"),
        有虚拟滚动: !!dd.querySelector(".vue-recycle-scroller"),
        子class: [...new Set([...dd.querySelectorAll("*")].slice(0, 200)
          .map((e) => (typeof e.className === "string" ? e.className : "").split(" ")[0]).filter(Boolean))].slice(0, 12),
      } : "弹层已消失";
      L.push(`[ERP] 渠道点法「${op.name}」弹层开但选项空，弹层内部=${JSON.stringify(info)}`);
      break;   // 弹层能开、问题在选项数据，换点法没用，停止
    }
    if (!labels.length) {
      // 到这说明：渠道输入框【定位到了】，但 5 种点法都没让 span.main_label 冒出来。
      // 打全诊断区分两类根因：①弹层压根没开(输入框失效/被遮罩拦点/触发层变了) ②弹层开了但选项空(数据/虚拟滚动)。
      const inp = chan();
      const dd = H.qsa(".el-popover, .select-menu, .el-select-dropdown").find((e) => H.isVisible(e));
      const diag = {
        输入框已连接: inp ? inp.isConnected : "输入框已消失",
        输入框: describeEl(inp),
        输入框disabled: inp ? !!(inp.disabled || inp.getAttribute("disabled") != null) : null,
        输入框readonly: inp ? !!inp.readOnly : null,   // el-select 类输入框 readonly=true 是常态，非病因
        祖先链class: ancestorClasses(inp),
        可见下拉容器数: H.qsa(".el-popover, .select-menu, .el-select-dropdown").filter(H.isVisible).length,
        弹层内文本: dd ? (dd.innerText || "").replace(/\s+/g, " ").trim().slice(0, 100) : "无可见下拉容器→弹层根本没开",
        可见弹层遮罩: visibleBlockers(),
      };
      L.push(`[ERP] ❌ 渠道下拉未取到选项（5 种点法都没弹出 span.main_label）。诊断=${JSON.stringify(diag)}`);
      return { ok: false, available: [], reason: dd ? "弹层已开但选项为空(数据/虚拟滚动)" : "弹层未弹开(触发/遮罩/输入框失效)" };
    }
    L.push(`[ERP] 渠道下拉已弹开（点法=${usedOpener}，${labels.length}项）`);
    // span.main_label 精确匹配（别用包含——订单行物流信息列也含渠道文字会误点）
    const picked = labels.find((el) => (el.innerText || "").trim() === channel);
    if (!picked) {
      const available = [...new Set(labels.map((e) => (e.innerText || "").trim()).filter(Boolean))].sort();
      L.push(`[ERP] 未找到渠道选项：${channel}；当前下拉可选渠道=${JSON.stringify(available)}`);
      try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
      return { ok: false, available };
    }
    H.realClick(picked);
    L.push(`[ERP] 渠道选中：${channel}`);

        if not picked:
            log(f"[ERP] 未找到筛选模板选项：{template_name}")
            try: page.keyboard.press("Escape")
            except Exception: pass
            return False
        time.sleep(2)
        log(f"[ERP] 已选择筛选模板：{template_name}")
        return True
    except Exception as e:
        log(f"[ERP] 选择筛选模板失败: {e}")
        return False


